function bookingPendingMove_(code) {
  const now = new Date();
  return calendar_().getEvents(now, new Date(now.getTime() + (CONFIG.DAYS_AHEAD + 1) * 864e5)).filter(function (e) {
    return (e.getTitle() || '').indexOf('改期待同意') >= 0 && (e.getDescription() || '').indexOf('改期自：' + code) >= 0;
  })[0] || null;
}
// 客人送出「改期申請」：先用一個暫時的行程佔住新時段，島主在控台按「確認成立」才真的改過去，按「取消」就維持原時間
function bookingMove(p) {
  p = p || {};
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const code = String(p.code || '').trim().toUpperCase(), e = bookingFind_(code, p.phone);
    if (!e) return {ok: false, error: '找不到這筆預約，請確認預約編號和手機。'};
    const i = bookingInfo_(e);
    if (!i.canChange) return {ok: false, error: i.reason};
    if (bookingPendingMove_(code)) return {ok: false, error: '您已經送出一次改期申請了，島主回覆前請先等一下；想換別的時段，直接 LINE 島主。'};
    if (!isBookableDate_(p.date) || !/^\d{2}:\d{2}$/.test(p.start || '')) return {ok: false, error: '日期或時間不正確，請重新選擇。'};
    if (p.date === i.date && p.start === i.start) return {ok: false, error: '這就是原本的時間喔，請選另一個時段。'};
    const slot = slotsFor_(p.date).filter(function (x) { return x.start === p.start; })[0];
    if (!slot || slot.fit < i.min) return {ok: false, error: '這個時段剛剛被預約走了，請換一個時間。'};
    const s = toMin_(p.start), old = i.date + ' ' + i.start, nw = p.date + ' ' + p.start + '–' + toTime_(s + i.min);
    const d = e.getDescription() || '', g = function (re) { return ((d.match(re) || [])[1] || '').trim(); };
    const name = g(/客人：([^\n]*)/), ph = g(/電話：([^\n]*)/);
    const h = calendar_().createEvent(CONFIG.TAG + '改期待同意｜' + i.service + '（原 ' + old + '）｜' + name, toDate_(p.date, s), toDate_(p.date, s + i.min), {description: [
      '改期自：' + code, '原預約ID：' + e.getId(), '療程：' + i.service, '客人：' + name, '電話：' + ph, '訂金：免付',
      '備註：客人申請從 ' + old + ' 改到 ' + nw + '。按「確認成立」＝同意改期；按「取消」＝維持原時間。',
      '建立時間：' + Utilities.formatDate(new Date(), CONFIG.TZ, 'yyyy-MM-dd HH:mm')].join('\n')});
    h.setColor(CalendarApp.EventColor.YELLOW);
    e.setDescription(/自己改期：\d+/.test(d) ? d.replace(/自己改期：\d+/, '自己改期：' + (i.changes + 1)) : d + '\n自己改期：1');
    let line = false;
    try { line = linePushPhone_(ph, '🌿 改期申請收到了！\n預約編號：' + code + '\n' + i.service + '\n想改到：' + nw + '\n（原本：' + old + '）\n\n島主同意後，會再用 LINE 通知您；在那之前，原本的時間都幫您保留著。'); } catch (x) {}
    try { linePushPhone_(OWNER_PHONE_, '🔁 有客人申請改時間\n' + name + '｜' + i.service + '\n' + old + ' → ' + nw + '\n\n到控台「Pause Space」預約頁：按「確認成立」＝同意，按「取消」＝維持原時間。'); } catch (x) {}
    return {ok: true, pending: true, service: i.service, date: p.date, start: p.start, end: toTime_(s + i.min), line: !!line};
  } finally { lock.releaseLock(); }
}
// 島主在控台對「改期待同意」按確認成立／取消
function moveDecide_(h, action) {
