  const item = parseEvent_(h), ph = g(/電話：([^\n]*)/), code = g(/改期自：([^\n]*)/), sv = g(/療程：([^\n]*)/);
  const nw = fmt_(h.getStartTime(), 'yyyy-MM-dd HH:mm') + '–' + fmt_(h.getEndTime(), 'HH:mm');
  let o = null; try { o = calendar_().getEventById(g(/原預約ID：([^\n]*)/)); } catch (x) {}
